/* Copy or combine stride512 quadrants into a dense stride256 operand. */
static inline void sera_strassen_pack_256(float *restrict destination,
                                         const float *first,
                                         const float *second,
                                         int sign) {
    for (int i = 0; i < 256; ++i) {
        float *out = destination + (size_t)i * 256;
        const float *row_first = first + (size_t)i * 512;
        if (second == NULL) {
            for (int j = 0; j < 256; ++j)
                out[j] = row_first[j];
        } else {
            const float *row_second = second + (size_t)i * 512;
            if (sign > 0) {
                for (int j = 0; j < 256; ++j)
                    out[j] = row_first[j] + row_second[j];
            } else {
                for (int j = 0; j < 256; ++j)
                    out[j] = row_first[j] - row_second[j];
            }
        }
    }
}

static inline void sera_strassen_product_256(const float *left,
                                            const float *right,
                                            float *product) {
    const void *parameters[22] = {0};
    parameters[4] = right;
    parameters[10] = left;
    parameters[16] = product;
    sera_libxsmm_256(parameters);
}

void gemm(int n, const float *A, const float *B, float *C) {
    if (n != 512) {
        fallback_gemm(n, A, B, C);
        return;
    }

    const size_t block_elements = (size_t)256 * 256;
    float *left = malloc(block_elements * sizeof(float));
    float *right = malloc(block_elements * sizeof(float));
    float *product = malloc(block_elements * sizeof(float));
    if (left == NULL || right == NULL || product == NULL) {
        free(left);
        free(right);
        free(product);
        fallback_gemm(n, A, B, C);
        return;
    }

    const float *a11 = A;
    const float *a12 = A + 256;
    const float *a21 = A + (size_t)256 * 512;
    const float *a22 = a21 + 256;
    const float *b11 = B;
    const float *b12 = B + 256;
    const float *b21 = B + (size_t)256 * 512;
    const float *b22 = b21 + 256;
    float *c11 = C;
    float *c12 = C + 256;
    float *c21 = C + (size_t)256 * 512;
    float *c22 = c21 + 256;

    for (size_t index = 0; index < (size_t)512 * 512; ++index)
        C[index] = 0.0f;

    /* P1 = (A11 + A22) (B11 + B22). */
    sera_strassen_pack_256(left, a11, a22, 1);
    sera_strassen_pack_256(right, b11, b22, 1);
    sera_strassen_product_256(left, right, product);
    for (int i = 0; i < 256; ++i) {
        for (int j = 0; j < 256; ++j) {
            const size_t output_index = (size_t)i * 512 + j;
            const float value = product[(size_t)i * 256 + j];
            c11[output_index] += value;
            c22[output_index] += value;
        }
    }

    /* P2 = (A21 + A22) B11. */
    sera_strassen_pack_256(left, a21, a22, 1);
    sera_strassen_pack_256(right, b11, NULL, 0);
    sera_strassen_product_256(left, right, product);
    for (int i = 0; i < 256; ++i) {
        for (int j = 0; j < 256; ++j) {
            const size_t output_index = (size_t)i * 512 + j;
            const float value = product[(size_t)i * 256 + j];
            c21[output_index] += value;
            c22[output_index] -= value;
        }
    }

    /* P3 = A11 (B12 - B22). */
    sera_strassen_pack_256(left, a11, NULL, 0);
    sera_strassen_pack_256(right, b12, b22, -1);
    sera_strassen_product_256(left, right, product);
    for (int i = 0; i < 256; ++i) {
        for (int j = 0; j < 256; ++j) {
            const size_t output_index = (size_t)i * 512 + j;
            const float value = product[(size_t)i * 256 + j];
            c12[output_index] += value;
            c22[output_index] += value;
        }
    }

    /* P4 = A22 (B21 - B11). */
    sera_strassen_pack_256(left, a22, NULL, 0);
    sera_strassen_pack_256(right, b21, b11, -1);
    sera_strassen_product_256(left, right, product);
    for (int i = 0; i < 256; ++i) {
        for (int j = 0; j < 256; ++j) {
            const size_t output_index = (size_t)i * 512 + j;
            const float value = product[(size_t)i * 256 + j];
            c11[output_index] += value;
            c21[output_index] += value;
        }
    }

    /* P5 = (A11 + A12) B22. */
    sera_strassen_pack_256(left, a11, a12, 1);
    sera_strassen_pack_256(right, b22, NULL, 0);
    sera_strassen_product_256(left, right, product);
    for (int i = 0; i < 256; ++i) {
        for (int j = 0; j < 256; ++j) {
            const size_t output_index = (size_t)i * 512 + j;
            const float value = product[(size_t)i * 256 + j];
            c11[output_index] -= value;
            c12[output_index] += value;
        }
    }

    /* P6 = (A21 - A11) (B11 + B12). */
    sera_strassen_pack_256(left, a21, a11, -1);
    sera_strassen_pack_256(right, b11, b12, 1);
    sera_strassen_product_256(left, right, product);
    for (int i = 0; i < 256; ++i) {
        for (int j = 0; j < 256; ++j)
            c22[(size_t)i * 512 + j] += product[(size_t)i * 256 + j];
    }

    /* P7 = (A12 - A22) (B21 + B22). */
    sera_strassen_pack_256(left, a12, a22, -1);
    sera_strassen_pack_256(right, b21, b22, 1);
    sera_strassen_product_256(left, right, product);
    for (int i = 0; i < 256; ++i) {
        for (int j = 0; j < 256; ++j)
            c11[(size_t)i * 512 + j] += product[(size_t)i * 256 + j];
    }

    free(left);
    free(right);
    free(product);
}
